.c-collapse-demo {
  --collapse-border: #d9d9d9;
  --collapse-header: rgb(0 0 0 / 2%);
  --collapse-hover: rgb(0 0 0 / 4%);
  --collapse-text: rgb(0 0 0 / 88%);
  --collapse-muted: rgb(0 0 0 / 45%);
  --collapse-primary: #1677ff;
  align-content: center;
  background: #f5f5f5;
  color: var(--collapse-text);
  display: grid;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  gap: .75rem;
  min-height: 100%;
  padding: 2rem;
}
.c-collapse { background: #fff; border: 1px solid var(--collapse-border); border-radius: .5rem; inline-size: min(100%, 42rem); margin-inline: auto; overflow: hidden; }
.c-collapse__item + .c-collapse__item { border-block-start: 1px solid var(--collapse-border); }
.c-collapse__heading { margin: 0; }
.c-collapse__trigger { align-items: center; background: var(--collapse-header); border: 0; color: inherit; cursor: pointer; display: flex; font: inherit; gap: .75rem; min-height: 3rem; padding: .75rem 1rem; text-align: start; width: 100%; }
.c-collapse__trigger:hover { background: var(--collapse-hover); }
.c-collapse__trigger:focus-visible { outline: 2px solid var(--collapse-primary); outline-offset: -2px; position: relative; z-index: 1; }
.c-collapse__icon { align-items: center; color: var(--collapse-muted); display: inline-flex; flex: 0 0 1rem; height: 1rem; justify-content: center; transition: transform .2s cubic-bezier(.645,.045,.355,1); }
.c-collapse__icon svg { fill: none; height: .8rem; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.7; width: .8rem; }
.c-collapse__trigger[aria-expanded="true"] .c-collapse__icon { transform: rotate(90deg); }
.c-collapse__title { flex: 1; font-size: .9rem; font-weight: 500; line-height: 1.55; }
.c-collapse__extra { color: var(--collapse-muted); font-size: .75rem; }
.c-collapse__panel { display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows .2s cubic-bezier(.645,.045,.355,1), opacity .2s ease; }
.c-collapse__panel[data-open="true"] { grid-template-rows: 1fr; opacity: 1; }
.c-collapse__panel-inner { min-height: 0; overflow: hidden; padding: 0 1rem; }
.c-collapse__panel[data-open="true"] .c-collapse__panel-inner { padding-block: 1rem; }
.c-collapse__panel-inner p { color: var(--collapse-text); font-size: .875rem; line-height: 1.6; margin: 0 0 .75rem; }
.c-collapse__panel-inner a { color: var(--collapse-primary); font-size: .875rem; text-decoration: none; }
.c-collapse__panel-inner a:hover { text-decoration: underline; }
.c-collapse-demo__hint { color: var(--collapse-muted); font-size: .76rem; inline-size: min(100%, 42rem); line-height: 1.5; margin: 0 auto; }
@media (max-width: 32rem) { .c-collapse-demo { padding: 1rem; } .c-collapse__trigger { padding-inline: .8rem; } }
@media (prefers-reduced-motion: reduce) { .c-collapse__icon, .c-collapse__panel { transition: none; } }

