export function createCollapse(root) {
  const triggers = [...root.querySelectorAll('[data-collapse-trigger]')];
  const pairs = triggers.map((trigger) => {
    const panel = document.getElementById(trigger.getAttribute('aria-controls'));
    if (!panel || !root.contains(panel)) throw new Error(`Missing collapse panel for ${trigger.id}.`);
    return { trigger, panel };
  });
  if (!pairs.length) throw new Error('Collapse markup is incomplete.');
  const onClick = (event) => {
    const trigger = event.currentTarget;
    const pair = pairs.find((item) => item.trigger === trigger);
    const expanded = trigger.getAttribute('aria-expanded') === 'true';
    trigger.setAttribute('aria-expanded', String(!expanded));
    pair.panel.setAttribute('aria-hidden', String(expanded));
    pair.panel.inert = expanded;
    pair.panel.dataset.open = String(!expanded);
  };
  pairs.forEach(({ trigger }) => trigger.addEventListener('click', onClick));
  return { destroy() { pairs.forEach(({ trigger }) => trigger.removeEventListener('click', onClick)); } };
}
document.querySelectorAll('[data-component="collapse"]').forEach(createCollapse);

