export function createSingleOpenCollapse(root) {
  const triggers = [...root.querySelectorAll('[data-collapse-trigger]')];
  const pairs = triggers.map((trigger) => {
    const panel = document.getElementById(trigger.getAttribute('aria-controls'));
    if (!panel || !root.contains(panel)) throw new Error(`Missing collapse panel for ${trigger.id}.`);
    return { trigger, panel };
  });
  if (!pairs.length) throw new Error('Accordion markup is incomplete.');
  const onClick = (event) => {
    const selected = pairs.find((item) => item.trigger === event.currentTarget);
    const opening = selected.trigger.getAttribute('aria-expanded') !== 'true';
    pairs.forEach(({trigger, panel}) => {
      const expanded = opening && trigger === selected.trigger;
      trigger.setAttribute('aria-expanded', String(expanded));
      panel.setAttribute('aria-hidden', String(!expanded));
      panel.inert = !expanded;
      panel.dataset.open = String(expanded);
    });
  };
  pairs.forEach(({trigger}) => trigger.addEventListener('click', onClick));
  return { destroy() { pairs.forEach(({trigger}) => trigger.removeEventListener('click', onClick)); } };
}
document.querySelectorAll('[data-component="collapse-accordion"]').forEach(createSingleOpenCollapse);
